#!/usr/bin/env node
"use strict";
// arcade-help-data.mjs -- tests for Leap Arcade's Help data (stage 5, P5): src/lang/arcade/arcade-help-data.js (GENERATED by tools/gen-arcade-help.mjs),
// the hand-written examples and pages (src/lang/arcade/arcade-help-examples.js) and the profile's Help entries.
//
//   node tests/arcade-help-data.mjs
//
// 1  the generated file is current (the generator, run in memory, gives the same text; `node tools/gen-arcade-help.mjs --check` says the same)
// 2  every word of the language table has an entry; every anchor is a heading of its document (GitHub slug); the profile's links use them
// 3  every example compiles with NO error and NO warning, inside a minimal game (the wrapper below); aliases point at an example
// 4  the pages: structure, every code block compiles the same way, every capitalised word the text names is a word of the language
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ARCADE_WORDS, REMOVED_WORDS } from '../src/lang/arcade/arcade-words.js';
import { compile, requiredRuntime } from '../src/lang/arcade/arcade-compile.js';
import { arcadeProfile } from '../src/lang/arcade/profile.js';
import { HELP_EXAMPLES, HELP_ALIASES, HELP_PAGES } from '../src/lang/arcade/arcade-help-examples.js';
import { ARCADE_HELP, DOCS_BASE } from '../src/lang/arcade/arcade-help-data.js';
import { generate, headingAnchors } from '../tools/gen-arcade-help.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
let passed = 0, failed = 0;
const check = (name, ok, detail = '') => {
  console.log(`  ${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  (' + detail + ')' : ''}`);
  ok ? passed++ : failed++;
  return ok;
};
const read = (p) => readFileSync(join(ROOT, p));

// ── the runtimes and the assets of the wrapper game ──────────────────────────────────────────────────────────────────────────────
const BUILDS = {};
for (const v of [2, 3, 4]) {
  BUILDS[v] = { runtime: JSON.parse(read(`arcade/dist/v${v}/runtime.json`).toString('utf8')), image: new Uint8Array(read(`arcade/dist/v${v}/runtime.bin`)) };
}
const example = (id) => JSON.parse(read(`arcade/dist/examples/${id}.leapgame`).toString('utf8')).assets;
const [shooter, breakout, runner, vaults, orbit] = ['shooter', 'breakout', 'runner', 'vaults', 'orbit'].map(example);

/** The asset names a help example may use, and where they come from (the pictures of the shipped example games): name -> [declaration kind, source table, source name]. */
const STD_ASSETS = {
  ship: ['SPRITE', 'sprites', shooter, 'ship'], bullet: ['SPRITE', 'sprites', shooter, 'bullet'], ball: ['SPRITE', 'sprites', breakout, 'ball'], bat: ['SPRITE', 'sprites', breakout, 'bat'],
  ghost: ['SPRITE', 'sprites', vaults, 'vl_wraith'], hero: ['SPRITE', 'sprites', runner, 'pf_hero'], walker: ['SPRITE', 'sprites', runner, 'pf_walker'],
  gfx: ['TILESET', 'tilesets', shooter, 'gfx'], tiles: ['TILESET', 'tilesets', runner, 'pf_tiles'],
  sky: ['MAP', 'maps', shooter, 'sky'], level: ['MAP', 'maps', runner, 'pf_world'], level2: ['MAP', 'maps', runner, 'rn_world2'], plan: ['MAP', 'maps', vaults, 'vl_maze'],
  zap: ['SFX', 'sfx', orbit, 'zap'], boom: ['SFX', 'sfx', orbit, 'boom'], pew: ['SFX', 'sfx', shooter, 'pew'],
  theme: ['MUSIC', 'music', orbit, 'theme'], gate: ['MODEL', 'models', orbit, 'gate'],
};
const ASSETS = { sprites: {}, tilesets: {}, maps: {}, sfx: {}, music: {}, models: {} };
for (const [name, [, table, src, from]] of Object.entries(STD_ASSETS)) ASSETS[table][name] = src[table][from];
/** The plain variables a fragment may use without declaring them; the wrapper DIMs the ones it names. */
const STD_VARS = ['x', 'y', 'dx', 'dy', 'score', 'lives', 't', 'n', 'js', 'row', 'flags', 'shots', 'speed', 'a', 'px', 'py', 'pz', 'pa', 'ea', 'd', 'ok', 'p'];
const STD_ARRAYS = { bx: 7 };
/** Lines at the left margin that belong at the top of the game (before the first scene). */
const GAME_LEVEL = /^(FRAMERATE|SPRITE|SFX|MUSIC|TILESET|MAP|MODEL|WINDOW|BAND|WIRE3D|VIEW3D)\b/i;
/** Lines that belong in a scene but outside its PROCs (single lines); the blocks that do are PROC ... ENDP and TABLE ... ENDTABLE. */
const SCENE_LEVEL = /^(DIM|TIMER|CONST|DEF)\b/i;

const declared = (text, word, name) => new RegExp(`^\\s*${word}\\s+${name}\\b`, 'im').test(text);
const mentions = (text, name) => new RegExp(`\\b${name}\\b`, 'i').test(text.replace(/REM.*$/gim, '').replace(/"[^"]*"/g, '""'));

/** The declarations of the standard assets a text names and does not declare itself. */
function assetLines(text) {
  const lines = [];
  for (const [name, [word]] of Object.entries(STD_ASSETS)) {
    if (!mentions(text, name) || declared(text, word, name)) continue;
    lines.push(`${word} ${name} = "${name}"`);
  }
  return lines;
}
/** A fragment -> a whole program (the wrapper described at the top of arcade-help-examples.js). */
export function wrap(text) {
  if (/^GAME\b/im.test(text)) return text;
  const lines = text.split('\n');
  const top = [], scene = [], body = [];
  const header = () => {
    const declares = (w) => new RegExp(`^\\s*${w}\\b`, 'im').test(text);
    const extra = [];
    const need = (word, name, line) => { if (!declared(text, word, name)) extra.push(line); };
    let rate = 30;
    if (!declares('WINDOW') && ['CAMERA', 'CAMX', 'SETWORLD', 'WORLDTILE', 'TILEFLAGS', 'TILEHIT', 'SOLID', 'WORLD'].some((w) => mentions(text, w))) {
      need('TILESET', 'tiles', 'TILESET tiles = "tiles"'); need('MAP', 'level', 'MAP level = "level"'); extra.push('WINDOW level');
    } else if (!declares('VIEW3D') && ['VIEW', 'SETWALL', 'WALL', 'SEEN', 'DEPTH'].some((w) => mentions(text, w))) {
      need('TILESET', 'gfx', 'TILESET gfx = "gfx"'); need('MAP', 'plan', 'MAP plan = "plan"'); extra.push('VIEW3D plan COLW 4 INK 5 CEIL 0 FLOOR 1'); rate = 20;
    } else if (!declares('WIRE3D') && ['EYE', 'DRAWMODEL', 'LINE'].some((w) => mentions(text, w))) {
      extra.push('WIRE3D ROWS 2 TO 21 INK 5 PAPER 0 BRIGHT 0');
    } else if (!/^\s*TILESET\b/im.test(text) && ['TILE', 'FILL', 'TILEAT', 'LOADMAP', 'MAP'].some((w) => mentions(text, w))) {
      extra.push('TILESET gfx = "gfx"');
    }
    if (declares('FRAMERATE')) rate = null;
    return ['GAME "Help"', ...(rate ? [`FRAMERATE ${rate}`] : []), ...extra, ...assetLines(text), ...top].join('\n') + '\n';
  };
  if (/^SCENE\b/im.test(text)) {
    for (const l of lines) (GAME_LEVEL.test(l) ? top : scene).push(l);       // scenes, with the game-level lines taken out
    return header() + scene.join('\n') + '\n';
  }
  let block = null;
  for (const l of lines) {
    if (block) { scene.push(l); if (new RegExp(`^${block}\\b`, 'i').test(l)) block = null; continue; }
    if (/^PROC\b/i.test(l)) { block = 'ENDP'; scene.push(l); }
    else if (/^TABLE\b/i.test(l)) { block = 'ENDTABLE'; scene.push(l); }
    else if (GAME_LEVEL.test(l)) top.push(l);
    else if (SCENE_LEVEL.test(l)) scene.push(l);
    else body.push(l);
  }
  const dims = STD_VARS.filter((v) => mentions(body.join('\n'), v) && !scene.some((l) => /^DIM\b/i.test(l) && new RegExp(`\\b${v}\\b`, 'i').test(l)));
  const arrays = Object.entries(STD_ARRAYS).filter(([a]) => mentions(body.join('\n'), a) && !scene.some((l) => new RegExp(`\\b${a}\\(`, 'i').test(l))).map(([a, n]) => `${a}(${n})`);
  const decl = [...(dims.length || arrays.length ? [`DIM ${[...dims, ...arrays].join(', ')}`] : []), ...scene];
  return header() + 'SCENE main\n' + decl.map((l) => '  ' + l).join('\n') + (decl.length ? '\n' : '')
    + '  PROC INIT():\n  ENDP\n  PROC FRAME():\n' + body.map((l) => '    ' + l).join('\n') + '\n  ENDP\nENDSCENE\n';
}
/** Compile a whole program with the runtime it needs; {errors, warnings}. */
export function compileText(text) {
  const need = requiredRuntime(text, ASSETS).version;
  const b = BUILDS[need] ?? BUILDS[2];
  return compile(text, { runtime: b.runtime, image: b.image, assets: ASSETS });
}
const problems = (res) => [...res.errors, ...res.warnings].map((d) => `line ${d.line}: ${d.message}`);

// ── 1: the generated file is current ──────────────────────────────────────────────────────────────────────────────────────────────
console.log('1. the generated data is current');
{
  const fresh = await generate(ROOT);
  const onDisk = readFileSync(join(ROOT, 'src/lang/arcade/arcade-help-data.js'), 'utf8');
  check('src/lang/arcade/arcade-help-data.js equals what tools/gen-arcade-help.mjs writes', fresh.text === onDisk);
  check('it carries the GENERATED header', /GENERATED/.test(onDisk.slice(0, 600)));
}

// ── 2: words, anchors, links ──────────────────────────────────────────────────────────────────────────────────────────────────────
console.log('2. every word has its manual section');
{
  const words = [...ARCADE_WORDS.values()].map((w) => w.name);
  const missing = words.filter((w) => !ARCADE_HELP[w]);
  check(`all ${words.length} words of the language table have an entry`, missing.length === 0, missing.join(' '));
  const extra = Object.keys(ARCADE_HELP).filter((w) => !ARCADE_WORDS.has(w));
  check('no entry for a word the language lacks', extra.length === 0, extra.join(' '));
  const heads = {};
  const headsOf = (f) => (heads[f] ??= new Set(headingAnchors(readFileSync(join(ROOT, 'docs', f), 'utf8')).map((h) => h.anchor)));
  const bad = [];
  for (const [w, e] of Object.entries(ARCADE_HELP)) if (e.anchor && !headsOf(e.doc).has(e.anchor)) bad.push(`${w} -> ${e.doc}#${e.anchor}`);
  check('every anchor is a heading of its document', bad.length === 0, bad.join('; '));
  const noAnchor = Object.entries(ARCADE_HELP).filter(([, e]) => !e.anchor).map(([w]) => w);
  check('every word links to a section, not to the top of a document', noAnchor.length === 0, noAnchor.join(' '));
  const help = arcadeProfile.help;
  let linkOk = true, shown = '';
  for (const [w, e] of Object.entries(ARCADE_HELP)) {
    const url = help.link(w, help.entries[w]);
    if (url !== `${DOCS_BASE}${e.doc}#${e.anchor}`) { linkOk = false; shown = `${w}: ${url}`; break; }
  }
  check('the profile\'s link(name) is <docs URL>/<document>#<anchor> for every word', linkOk, shown);
  check('the profile\'s entries carry the example of the data', Object.entries(ARCADE_HELP).every(([w, e]) => help.entries[w].example === e.example));
}

// ── 3: the examples compile ───────────────────────────────────────────────────────────────────────────────────────────────────────
console.log('3. every example compiles (no error, no warning)');
{
  const names = Object.keys(HELP_EXAMPLES);
  check('every example is for a word of the language', names.every((n) => ARCADE_WORDS.has(n)), names.filter((n) => !ARCADE_WORDS.has(n)).join(' '));
  check('every alias names a word and an example', Object.entries(HELP_ALIASES).every(([a, b]) => ARCADE_WORDS.has(a) && HELP_EXAMPLES[b]));
  check('no example is longer than 24 lines', names.every((n) => HELP_EXAMPLES[n].split('\n').length <= 24), names.filter((n) => HELP_EXAMPLES[n].split('\n').length > 24).join(' '));
  check('no example is empty or has a tab', names.every((n) => HELP_EXAMPLES[n].trim() !== '' && !HELP_EXAMPLES[n].includes('\t')));
  for (const n of names) {
    const prog = wrap(HELP_EXAMPLES[n]);
    let res;
    try { res = compileText(prog); } catch (e) { res = { errors: [{ line: 0, message: 'threw: ' + e.message }], warnings: [] }; }
    const p = problems(res);
    check(`example ${n}`, p.length === 0 && !!res.dck, p.join(' | ') || (res.dck ? '' : 'no dck'));
    if (p.length && process.env.SHOW) console.log(prog.split('\n').map((l, i) => String(i + 1).padStart(3) + '  ' + l).join('\n'));
  }
  const noExample = [...ARCADE_WORDS.keys()].filter((w) => !HELP_EXAMPLES[w] && !HELP_ALIASES[w]);
  console.log(`  INFO  words with no example (${noExample.length}): ${noExample.join(' ')}`);
  // Every word of the table has an example: the compiler takes every word it lists (language batch 8 built END TAB FLASH PEEK POKE and took LEN USR OUT IN PLOT POINT out of the table).
  check('every word of the table has an example (the compiler refuses none of them any more)', noExample.length === 0, noExample.join(' '));
  // The six words Leap V2 has and Leap Arcade does not are not in the table (so no Help entry), but stay reserved and say why.
  const REMOVED = { LEN: 'x = LEN("A")', USR: 'x = USR(32768)', OUT: 'OUT 254, 2', IN: 'x = IN(254)', PLOT: 'PLOT 1, 1', POINT: 'x = POINT(1, 1)' };
  check('the removed words are exactly the six of REMOVED_WORDS', Object.keys(REMOVED).sort().join(' ') === [...REMOVED_WORDS.keys()].sort().join(' '));
  for (const [w, probe] of Object.entries(REMOVED)) {
    const res = compileText(wrap(probe));
    check(`${w} is not in the table, has no Help entry and is refused with "is not part of Leap Arcade"`, !ARCADE_WORDS.has(w) && !ARCADE_HELP[w] && res.errors.some((d) => d.message.startsWith(`${w} is not part of Leap Arcade: `)), res.errors.map((d) => d.message).join(' | '));
  }
}

// ── 4: the pages ──────────────────────────────────────────────────────────────────────────────────────────────────────────────────
console.log('4. the pages');
{
  check('the first page is "How a game is built"', HELP_PAGES[0]?.title === 'How a game is built');
  check('the profile\'s help.pages is HELP_PAGES', arcadeProfile.help.pages === HELP_PAGES);
  check('every page has an id, a title and blocks of a known type', HELP_PAGES.every((p) => p.id && p.title && p.blocks.length && p.blocks.every((b) => ['h', 'p', 'code'].includes(b.type) && typeof b.text === 'string' && b.text.trim() !== '')));
  const wordRe = /\b[A-Z]{2,}[A-Z0-9]*\$?\b/g;
  const known = new Set([...ARCADE_WORDS.keys(), 'DCK', 'TSRun', 'TS2068', 'UDG', 'ZEsarUX', 'Fuse', 'AY', 'MAP', 'ROM', 'RAM', 'KB', 'GAME', 'ARC', 'HIT']);
  for (const page of HELP_PAGES) {
    let k = 0;
    for (const b of page.blocks) {
      if (b.type === 'code') {
        const prog = wrap(b.text);
        const p = problems(compileText(prog));
        check(`page "${page.title}" code block ${++k} compiles`, p.length === 0, p.join(' | '));
      } else {
        const stray = (b.text.match(wordRe) ?? []).filter((w) => !known.has(w));
        check(`page "${page.title}" ${b.type} "${b.text.slice(0, 30)}…" names only words of the language`, stray.length === 0, stray.join(' '));
      }
    }
  }
}

console.log(`\n${failed === 0 ? 'PASS' : 'FAIL'}: arcade-help-data (${passed} passed, ${failed} failed)`);
process.exit(failed === 0 ? 0 : 1);
